import { unzipSync } from 'fflate'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { UpdateCycleLocal } from '../../../data/updateCycleRepo'
import { json, mockFetch, problem } from '../../../test/fetch-mock'
import { newTestApi } from '../../../test/localDb'
import { buildPhotosZip, downloadCyclePhotos, photoEntryName, PhotosDownloadError } from './photosZip'

const FILE_1 = '5b0f7c1e-1d2a-4b3c-8d4e-0000000000f1'
const FILE_2 = '5b0f7c1e-1d2a-4b3c-8d4e-0000000000f2'

// Generated bytes, never a real photo.
const bytes = (seed: number) => new Uint8Array([0xff, 0xd8, seed, seed + 1, 0xff, 0xd9])

const unzip = async (blob: Blob) => unzipSync(new Uint8Array(await blob.arrayBuffer()))

const cycle = (): UpdateCycleLocal => ({
  id: '5b0f7c1e-1d2a-4b3c-8d4e-000000000001',
  protocolVersionId: '5b0f7c1e-1d2a-4b3c-8d4e-0000000000aa',
  periodStart: '2026-10-05',
  periodEnd: '2026-10-26',
  status: 'draft',
  answers: {},
  photos: [
    { pose: 'back', fileId: FILE_2, takenAt: '2026-10-19T09:01:00.000Z' },
    { pose: 'front', fileId: FILE_1, takenAt: '2026-10-19T09:00:00.000Z' },
  ],
  sentAt: null,
  clientUpdatedAt: '2026-10-19T10:00:00.000Z',
})

afterEach(() => vi.unstubAllGlobals())

describe('buildPhotosZip', () => {
  it('reopens with the same names and bytes', async () => {
    const zip = buildPhotosZip([
      { name: photoEntryName(0, 'front'), bytes: bytes(1) },
      { name: photoEntryName(1, 'right_side'), bytes: bytes(2) },
    ])

    expect(zip.type).toBe('application/zip')
    const files = await unzip(zip)
    expect(Object.keys(files)).toEqual(['01-front.jpg', '02-right_side.jpg'])
    expect([...files['01-front.jpg']!]).toEqual([...bytes(1)])
    expect([...files['02-right_side.jpg']!]).toEqual([...bytes(2)])
  })
})

describe('downloadCyclePhotos', () => {
  const routes = () => ({
    [`GET /api/files/${FILE_1}/download-url`]: () => json({ url: 'http://storage.test/get/1', expiresAt: '2026-10-19T12:05:00Z' }),
    [`GET /api/files/${FILE_2}/download-url`]: () => json({ url: 'http://storage.test/get/2', expiresAt: '2026-10-19T12:05:00Z' }),
    'GET /get/1': () => new Response(bytes(1)),
    'GET /get/2': () => new Response(bytes(2)),
  })

  it('downloads each photo by its signed URL, in the template order of the poses', async () => {
    const calls = mockFetch(routes())

    const files = await unzip(await downloadCyclePhotos(cycle(), newTestApi(), [{ key: 'front' }, { key: 'back' }]))

    expect(Object.keys(files)).toEqual(['01-front.jpg', '02-back.jpg'])
    expect([...files['02-back.jpg']!]).toEqual([...bytes(2)])
    expect(calls.filter((c) => c.path.startsWith('/get/'))).toHaveLength(2)
    for (const c of calls.filter((c) => c.path.startsWith('/get/'))) expect(c.headers.get('authorization')).toBeNull()
  })

  it('without poses keeps the cycle order', async () => {
    mockFetch(routes())
    const files = await unzip(await downloadCyclePhotos(cycle(), newTestApi()))
    expect(Object.keys(files)).toEqual(['01-back.jpg', '02-front.jpg'])
  })

  it('a failed URL, a failed download or no connection rejects with the screen message', async () => {
    mockFetch({ ...routes(), [`GET /api/files/${FILE_1}/download-url`]: () => problem(404, { title: 'x' }) })
    await expect(downloadCyclePhotos(cycle(), newTestApi())).rejects.toThrow(new PhotosDownloadError('Não foi possível baixar as fotos. Tente novamente.'))

    mockFetch({ ...routes(), 'GET /get/2': () => new Response(null, { status: 403 }) })
    await expect(downloadCyclePhotos(cycle(), newTestApi())).rejects.toBeInstanceOf(PhotosDownloadError)

    mockFetch({})
    await expect(downloadCyclePhotos(cycle(), newTestApi())).rejects.toBeInstanceOf(PhotosDownloadError)
  })
})
